import marshal, py_compile, importlib.util, os, dis, io, tempfile

def dump(code):
    out = io.StringIO()
    def walk(c):
        out.write(repr(c.co_name)+' '+repr(c.co_code)+' '+repr(c.co_consts)+' '+repr(c.co_names)+' '+repr(c.co_varnames)+'\n')
        for k in c.co_consts:
            if hasattr(k,'co_code'):
                walk(k)
    walk(code)
    return out.getvalue()

for name in ('conftest','test_basic'):
    pyc = 'tests/__pycache__/%s.cpython-311-pytest-9.1.1.pyc' % name
    src = 'tests/%s.py' % name
    cached = marshal.loads(open(pyc,'rb').read()[16:])
    fresh = compile(open(src,'rb').read(), cached.co_filename, 'exec')
    a, b = dump(cached), dump(fresh)
    print(name, 'MATCH' if a==b else 'DIFFER')
    if a!=b:
        la, lb = a.splitlines(), b.splitlines()
        print(' cached lines:', len(la), 'fresh lines:', len(lb))
        for x,y in zip(la,lb):
            if x!=y:
                print('  CACHED:', x[:300])
                print('  FRESH :', y[:300])
