import marshal, types

def norm(code):
    consts = tuple('<code %s>' % c.co_name if isinstance(c, types.CodeType) else c
                   for c in code.co_consts)
    kids = [norm(c) for c in code.co_consts if isinstance(c, types.CodeType)]
    return (code.co_name, code.co_argcount, code.co_varnames, code.co_names,
            consts, code.co_code)

def by_name(code):
    d = {}
    for c in code.co_consts:
        if isinstance(c, types.CodeType):
            d.setdefault(c.co_name, []).append(norm(c))
    return d

for name in ('conftest','test_basic'):
    src = 'tests/%s.py' % name
    cached = marshal.loads(open('tests/__pycache__/%s.cpython-311-pytest-9.1.1.pyc' % name,'rb').read()[16:])
    fresh = compile(open(src,'rb').read(), cached.co_filename, 'exec')
    a, b = by_name(cached), by_name(fresh)
    print('=====', name)
    for k in sorted(set(a) | set(b)):
        if a.get(k) != b.get(k):
            print(' DIFF in', k)
            for x, y in zip(a.get(k, []), b.get(k, [])):
                if x != y:
                    for i, label in enumerate(['name','argcount','varnames','names','consts','code']):
                        if x[i] != y[i]:
                            print('   cached.%s = %r' % (label, x[i]))
                            print('   fresh .%s = %r' % (label, y[i]))
        else:
            print(' same:', k)
